1	import { Injectable, OnModuleInit } from '@nestjs/common';
2	import { ConfigService } from '@nestjs/config';
3	import * as jose from 'jose';
4	import { createPublicKey } from 'node:crypto';
5	import { Clock } from '../../common/clock';
6	import type { IdentitySubjectKind } from '../entities/identity-subject.entity';
7	
8	const KID = 'cipherbox-identity-1';
9	const ALGORITHM = 'RS256';
10	
11	/** Who mints the token, and who is entitled to verify it. */
12	export const IDENTITY_TOKEN_ISSUER = 'cipherbox';
13	export const IDENTITY_TOKEN_AUDIENCE = 'web3auth';
14	
15	/** Long enough for the Core Kit handshake, short enough that a leak is stale. */
16	const TOKEN_TTL_SECONDS = 300;
17	
18	export interface IdentityTokenClaims {
19	  /** The `identity_subjects` row id — the Core Kit `verifierId`. */
20	  subject: string;
21	  method: IdentitySubjectKind;
22	}
23	
24	/**
25	 * Mints the identity token the Core Kit consumes, and serves the JWKS the
26	 * Web3Auth custom verifier fetches to check it (ADR 0008 D1).
27	 */
28	@Injectable()
29	export class IdentityTokenService implements OnModuleInit {
30	  private signingKey!: jose.CryptoKey | jose.KeyObject;
31	  private publicJwk!: jose.JWK;
32	
33	  constructor(
34	    private readonly configService: ConfigService,
35	    private readonly clock: Clock
36	  ) {}
37	
38	  async onModuleInit(): Promise<void> {
39	    const nodeEnv = this.configService.get<string>('NODE_ENV') ?? 'development';
40	    const encodedPem = this.configService.get<string>('IDENTITY_JWT_PRIVATE_KEY');
41	
42	    if (encodedPem) {
43	      // Base64-encoded because a multiline PEM does not survive a .env file.
44	      const pem = Buffer.from(encodedPem, 'base64').toString('utf8');
45	      this.signingKey = await jose.importPKCS8(pem, ALGORITHM);
46	      this.publicJwk = await this.exportPublicJwk(createPublicKey(pem));
47	      return;
48	    }
49	
50	    // Allowlisted exactly as `buildJwtOptions` allowlists the JWT secret, and
51	    // for a sharper reason: Torus caches the JWKS per URL, so a keypair
52	    // regenerated on restart makes every later login fail verification against
53	    // the cached public half — surfacing as `crypto/rsa: verification error`,
54	    // which names neither the key nor the restart.
55	    if (nodeEnv !== 'development' && nodeEnv !== 'test') {
56	      throw new Error(
57	        `IDENTITY_JWT_PRIVATE_KEY is required when NODE_ENV is '${nodeEnv}' — ` +
58	          'generate with: openssl genpkey -algorithm RSA -pkeyopt rsa_keygen_bits:2048 | base64 -w0'
59	      );
60	    }
61	    const { publicKey, privateKey } = await jose.generateKeyPair(ALGORITHM, {
62	      modulusLength: 2048,
63	    });
64	    this.signingKey = privateKey;
65	    this.publicJwk = await this.exportPublicJwk(publicKey);
66	  }
67	
68	  /** The public half only; the JWKS is world-readable by design. */
69	  jwks(): { keys: jose.JWK[] } {
70	    return { keys: [this.publicJwk] };
71	  }
72	
73	  /**
74	   * Sign an identity token for an already-verified provider identity. The
75	   * `method` claim rides along so a restored Core Kit session can still name
76	   * how it was established — `getUserInfo()` reflects the token's own claims.
77	   */
78	  async sign(claims: IdentityTokenClaims): Promise<{ token: string; expiresAt: Date }> {
79	    const issuedAt = Math.floor(this.clock.now().getTime() / 1000);
80	    const expiresAt = issuedAt + TOKEN_TTL_SECONDS;
81	    const token = await new jose.SignJWT({ method: claims.method })
82	      .setProtectedHeader({ alg: ALGORITHM, kid: KID })
83	      .setSubject(claims.subject)
84	      .setIssuer(IDENTITY_TOKEN_ISSUER)
85	      .setAudience(IDENTITY_TOKEN_AUDIENCE)
86	      .setIssuedAt(issuedAt)
87	      .setExpirationTime(expiresAt)
88	      .sign(this.signingKey);
89	    return { token, expiresAt: new Date(expiresAt * 1000) };
90	  }

